import { atom, read, update } from 'claude-code'
import type { EngineInterface, RenderChildren, PluginOptions, Register } from 'claude-code'

import {
  bandCacheText,
  bandLayout,
  bandVisible,
  cacheMinutesLeft,
  cacheNudge,
  EXPENSIVE_PER_TURN,
  frontmatterModel,
  gaugeFit,
  gaugeSegments,
  HANDOFF_LABEL,
  heavyAlerts,
  IGNORE_LABEL,
  isHandoffDraft,
  learnedModel,
  requestsFable,
  resolveModel,
  tierOf,
  turnDelta,
  type Tone,
} from './logic'

// Everything lives in $.state so a hot reload keeps the turn's count.
const prompt = atom({ plugin: 'burn-guard', key: 'prompt' } as const, '')
const spawns = atom({ plugin: 'burn-guard', key: 'spawns' } as const, 0)
const turnBase = atom({ plugin: 'burn-guard', key: 'turnBase' } as const, null)
const lastResponseAt = atom({ plugin: 'burn-guard', key: 'lastResponseAt' } as const, null)
const nudgedFor = atom({ plugin: 'burn-guard', key: 'nudgedFor' } as const, null)
const lastFiveHour = atom({ plugin: 'burn-guard', key: 'lastFiveHour' } as const, null)
const heavyAlerted = atom({ plugin: 'burn-guard', key: 'heavyAlerted' } as const, false)
/** The usage readings the gauge row draws; written only when one changes, so it redraws at most once a minute. */
const readings = atom({ plugin: 'burn-guard', key: 'readings' } as const, null)

/** The manifest's userConfig, typed; both alerts default off. */
type Config = {
  nudgeLeadMs: number | null
  heavy: { turnPct: number; windowPct: number } | null
  fableManualOnly: boolean
}

function readConfig(options: PluginOptions): Config {
  const bool = (k: string) => options[k] === true
  const num = (k: string, d: number) => {
    const v = options[k]
    return typeof v === 'number' ? v : d
  }
  return {
    nudgeLeadMs: bool('cacheNudge') ? num('cacheNudgeMinutes', 5) * 60_000 : null,
    heavy: bool('heavyTurnAlert') ? { turnPct: num('heavyTurnPercent', 5), windowPct: num('windowAlertPercent', 80) } : null,
    fableManualOnly: options.fableManualOnly !== false,
  }
}

/** Text props per gauge tone. */
const TONE: Record<Tone, { color?: string; dimColor?: boolean }> = {
  plain: {},
  dim: { dimColor: true },
  info: { color: 'cyan' },
  meta: { color: 'magenta' },
  ok: { color: 'green' },
  warn: { color: 'yellow' },
  bad: { color: 'red' },
}

const learnedKey = (subagentType: string) => `learned-model:${subagentType}`

async function learned($: EngineInterface, subagentType: string): Promise<string | undefined> {
  const v = await $.store.get(learnedKey(subagentType))
  return typeof v === 'string' ? v : undefined
}

const USER_ORIGINS = new Set(['composer', 'bridge', 'sdk'])

async function fiveHourPercent($: EngineInterface): Promise<number | undefined> {
  const { rateLimits } = await $.session.usage()
  return rateLimits.find(r => r.kind === 'five_hour')?.percentUsed
}

/** Re-read usage and cache warmth for the gauge row, and fire the cache nudge. */
async function refreshStatus($: EngineInterface, config: Config): Promise<void> {
  const { rateLimits, context } = await $.session.usage()
  const five = rateLimits.find(r => r.kind === 'five_hour')
  const fiveHour = five?.percentUsed
  // No reading at turn start (first turn of a session): base on the first one seen.
  if ((await read($, turnBase)) === null && fiveHour !== undefined) await update($, turnBase, () => fiveHour)
  const now = await $.clock.now()
  const last = await read($, lastResponseAt)
  const left = cacheMinutesLeft(now, last)
  if ((await read($, cacheLeftMin)) !== left) await update($, cacheLeftMin, () => left)
  const next = {
    fiveHour: fiveHour ?? null,
    fiveHourResetsAt: five?.resetsAt ?? null,
    sevenDay: rateLimits.find(r => r.kind === 'seven_day')?.percentUsed ?? null,
    contextTokens: context.tokens ?? null,
  }
  const prev = await read($, readings)
  if (prev === null || (Object.keys(next) as (keyof typeof next)[]).some(k => prev[k] !== next[k])) {
    await update($, readings, () => next)
  }
  if (config.nudgeLeadMs !== null) {
    const nudge = cacheNudge({ now, lastResponseAt: last, nudgedFor: await read($, nudgedFor), leadMs: config.nudgeLeadMs })
    if (nudge !== undefined) {
      await update($, nudgedFor, () => last)
      $.ui.toast(nudge, { timeoutMs: 15_000 })
    }
  }
}

/** The `model:` frontmatter of a subagent definition: project agents first, then user agents. */
async function definitionModel($: EngineInterface, subagentType: string): Promise<string | undefined> {
  const home = await $.env.get('HOME')
  const dirs = [`${await $.session.root()}/.claude/agents`, ...(home ? [`${home}/.claude/agents`] : [])]
  for (const dir of dirs) {
    try {
      return frontmatterModel(await $.fs.read(`${dir}/${subagentType}.md`))
    } catch {
      // Not defined in this directory; try the next.
    }
  }
  return undefined
}

function deny($: EngineInterface, reason: string, toast: string): { deny: string } {
  $.ui.toast(`burn-guard denied: ${toast}`, { timeoutMs: 8000 })
  return { deny: `burn-guard: ${reason}` }
}

// The handoff band: past a context size, offer /session-handoff then /clear.
// There is deliberately no compaction path. All band state lives in $.state,
// so a hot reload (a config change, an edit) keeps it.

/** Written by burn-guard's minute tick; the band reads it while drawing, so it re-renders on its own. */
const cacheLeftMin = atom({ plugin: 'burn-guard', key: 'cacheLeftMin' } as const, null)
const bandSize = atom({ plugin: 'burn-guard', key: 'bandSize' } as const, null)
const ignoredAt = atom({ plugin: 'burn-guard', key: 'bandIgnoredAt' } as const, null)
const quiet = atom({ plugin: 'burn-guard', key: 'bandQuiet' } as const, false)
const pressedAt = atom({ plugin: 'burn-guard', key: 'handoffPressedAt' } as const, null)
const handoffDraft = atom({ plugin: 'burn-guard', key: 'handoffDraft' } as const, null)

const HANDOFF_COMMAND = 'session-handoff'

type BandConfig = { threshold: number; step: number; handoffFile: string }

function readBandConfig(options: PluginOptions): BandConfig {
  const num = (k: string, d: number) => {
    const v = options[k]
    return typeof v === 'number' ? v : d
  }
  const file = options.handoffFile
  return {
    threshold: num('handoffBandTokens', 150_000),
    step: num('handoffBandStep', 50_000),
    handoffFile: typeof file === 'string' ? file : '',
  }
}

async function handoffPath($: EngineInterface, config: BandConfig): Promise<string | undefined> {
  if (config.handoffFile !== '') return config.handoffFile
  const home = await $.env.get('HOME')
  return home ? `${home}/.claude/handoffs/latest.md` : undefined
}

/** Turn-end decision: show the band for the context the next request re-sends, or hide it. */
async function refreshBand($: EngineInterface, config: BandConfig, isInteractive: boolean): Promise<void> {
  const size = isInteractive ? (await $.session.usage()).context.tokens : undefined
  const show = bandVisible({
    size,
    threshold: config.threshold,
    step: config.step,
    ignoredAt: await read($, ignoredAt),
    quiet: await read($, quiet),
  })
  await update($, bandSize, () => (show && size !== undefined ? size : null))
}

/** [h]: record the press, hide the band, run /session-handoff (or leave it in the prompt box). */
async function startHandoff($: EngineInterface): Promise<void> {
  const now = await $.clock.now()
  await update($, pressedAt, () => now)
  await update($, handoffDraft, () => null)
  await update($, bandSize, () => null)
  try {
    await $.command.run({ command: HANDOFF_COMMAND })
  } catch {
    const { isFilled } = await $.prompt.fill({ text: `/${HANDOFF_COMMAND}` })
    $.ui.toast(isFilled ? 'press Enter to run /session-handoff' : 'type /session-handoff', { timeoutMs: 10_000 })
  }
}

/** [i]: the first hides the band until the context grows `step`; a second quiets it for the session. */
async function ignoreBand($: EngineInterface): Promise<void> {
  const size = await read($, bandSize)
  if ((await read($, ignoredAt)) !== null) {
    await update($, quiet, () => true)
    $.ui.toast('handoff band quiet for this session', { timeoutMs: 6000 })
  } else if (size !== null) {
    await update($, ignoredAt, () => size)
  }
  await update($, bandSize, () => null)
}

/**
 * At turn end: if an [h] press is pending, this was its handoff turn — clear
 * only when the handoff file was written after the press. Otherwise refresh.
 */
async function bandTurnComplete($: EngineInterface, config: BandConfig, isInteractive: boolean): Promise<void> {
  const pressed = await read($, pressedAt)
  if (pressed === null) return refreshBand($, config, isInteractive)
  await update($, pressedAt, () => null) // one check per press: never a second clear
  const draft = await read($, handoffDraft)
  await update($, handoffDraft, () => null)

  // Saved = written after the press AND holding this session's own handoff. The mtime
  // alone isn't proof: a parallel session can pin its own handoff as latest.md meanwhile.
  const path = await handoffPath($, config)
  const stat = path === undefined ? undefined : await $.fs.stat(path).catch(() => undefined)
  const latest = stat !== undefined && stat.kind === 'file' && stat.mtimeMs > pressed && path !== undefined
    ? await $.fs.read(path).catch(() => undefined)
    : undefined
  const own = draft === null ? undefined : await $.fs.read(draft).catch(() => undefined)
  if (latest === undefined || own === undefined || own.trim() === '' || latest !== own) {
    $.ui.toast('handoff not saved — not clearing', { timeoutMs: 15_000 })
    return refreshBand($, config, isInteractive)
  }
  await update($, bandSize, () => null)
  // /clear can't run inside the turn.complete dispatch the turn waits on: run it once that settles.
  $.clock.after(0, () => {
    $.command.run({ command: 'clear' }).catch(() => $.ui.toast('handoff saved — type /clear', { timeoutMs: 15_000 }))
  })
}

/** /clear starts a new conversation with no session.start: re-arm the band for it. */
async function resetBand($: EngineInterface): Promise<void> {
  await update($, bandSize, () => null)
  await update($, ignoredAt, () => null)
  await update($, quiet, () => false)
  await update($, pressedAt, () => null)
  await update($, handoffDraft, () => null)
}

export const register: Register = (on, options) => {
  const config = readConfig(options)
  const bandConfig = readBandConfig(options)
  // A fact about this process, not band state: session.start re-sets it on every (re)load.
  let isInteractive = false

  on('session.start', async ($, e, next) => {
    isInteractive = e.isInteractive
    $.ui.status(undefined) // the gauge row replaces the old one-line status
    $.clock.every(60_000, () => void refreshStatus($, config))
    await refreshStatus($, config)
    return next(e)
  })

  on('prompt.submit', async ($, e, next) => {
    if (USER_ORIGINS.has(e.origin.kind)) {
      // Typed mid-turn: it joins the running turn's prompt rather than replacing it.
      await update($, prompt, p => (e.turnId === undefined ? e.text : `${p}\n${e.text}`))
    } else if (e.turnId === undefined) {
      await update($, prompt, () => '') // a turn the user didn't start
    }
    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    await update($, spawns, () => 0)
    await update($, turnBase, () => null)
    const fiveHour = await fiveHourPercent($)
    if (fiveHour !== undefined) await update($, turnBase, () => fiveHour)
    await update($, heavyAlerted, () => false)
    if (e.text === '') await update($, prompt, () => '')
    await refreshStatus($, config)
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    const result = yield* next(e)
    if (e.agentId === undefined) {
      const now = await $.clock.now()
      await update($, lastResponseAt, () => now)
      await refreshStatus($, config)
    }
    return result
  })

  on('session.measure', async ($, e, next) => {
    const current = e.rateLimits.find(r => r.kind === 'five_hour')?.percentUsed
    if (current !== undefined) {
      const previous = await read($, lastFiveHour)
      await update($, lastFiveHour, () => current)
      if (config.heavy !== null) {
        const alerts = heavyAlerts({
          base: await read($, turnBase),
          previous,
          current,
          turnAlerted: await read($, heavyAlerted),
          ...config.heavy,
        })
        await update($, heavyAlerted, () => alerts.turnAlerted)
        for (const t of alerts.toasts) $.ui.toast(`burn-guard: ${t}`, { timeoutMs: 10_000 })
      }
    }
    await refreshStatus($, config)
    return next(e)
  })

  // The engine's resolved model is known only once the subagent has started
  // (agent.spawn's next(e) resolves after the start), too late to deny on. So
  // the guard stays on tool.call; this records what a call naming no model
  // actually ran on, so the next spawn of that type decides on the real model.
  on('agent.spawn', async ($, e, next) => {
    const result = await next(e)
    if (result.deny === undefined && e.model === undefined && !e.fork && !(await $.env.get('CLAUDE_CODE_SUBAGENT_MODEL'))) {
      const model = learnedModel(result.model, e.parentModel)
      if (model === undefined) await $.store.delete(learnedKey(e.subagentType))
      else await $.store.set(learnedKey(e.subagentType), model)
    }
    return result
  })

  on('tool.call', { tool: 'Agent' }, async ($, e, next) => {
    const session = await $.session.model()
    const subagentType = e.subagent_type
    const { model, source } = resolveModel({
      subagentType,
      inputModel: e.model,
      frontmatter: subagentType === undefined ? undefined : await definitionModel($, subagentType),
      learned: await learned($, subagentType ?? 'general-purpose'),
      defaultSubagent: await $.env.get('CLAUDE_CODE_SUBAGENT_MODEL'),
      session,
    })
    const tier = tierOf(model)
    const label = `${subagentType ?? 'general-purpose'} on ${model} (from ${source})`

    if (tier === 'cheap') return next(e)

    if (tier === 'fable' && config.fableManualOnly && tierOf(session) !== 'fable' && !requestsFable(await read($, prompt))) {
      return deny(
        $,
        `Fable-tier spawn blocked: ${label}. Fable is manual-only. Ask the user first; spawn it only after they explicitly ask for Fable in their reply.`,
        `Fable spawn ${label}`,
      )
    }

    const count = await update($, spawns, n => n + 1)
    if (count > EXPENSIVE_PER_TURN) {
      await update($, spawns, n => n - 1)
      await refreshStatus($, config)
      return deny(
        $,
        `expensive-tier spawn #${count} this turn blocked: ${label}. The limit is ${EXPENSIVE_PER_TURN} per turn. Get the user's confirmation before spawning more, or pin the agent to sonnet/haiku.`,
        `expensive spawn #${count} ${label}`,
      )
    }
    await refreshStatus($, config)
    return next(e)
  }).catch(($, e, next) =>
    // Fail closed: a guard that crashed before deciding must not wave the spawn through.
    next.called
      ? next(e)
      : deny($, `the spawn guard failed (${next.error.kind}: ${next.error.message ?? "no message"}) before it could check this spawn. Tell the user; don't retry.`, 'guard error'),
  )

  // While an [h] handoff runs, note the dated file this session's own Write saves.
  on('tool.call', { tool: 'Write' }, async ($, e, next) => {
    const result = await next(e)
    const isSaved = result.deny === undefined && result.isError !== true
    if (isSaved && e.agentId === undefined && isHandoffDraft(e.file_path) && (await read($, pressedAt)) !== null) {
      await update($, handoffDraft, () => e.file_path)
    }
    return result
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId === undefined) await bandTurnComplete($, bandConfig, isInteractive)
    return result
  })

  on('session.end', async ($, e, next) => {
    if (e.reason === 'clear') await resetBand($)
    return next(e)
  })

  // Above the prompt: the usage gauge (always, even mid-turn) and, past a context size at
  // turn end, the handoff band beneath it. Headless never raises AbovePrompt and
  // refreshBand never arms the band there. The band has two buttons only — no compaction path.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || e.props.view.agentId !== undefined) return next(e)
    const { Box, Button, Text } = $.ui.resolve(e)
    // The band is one site shared by every mod: stack our row on what the mods beneath draw, never replace it.
    const withBelow = async (mine: RenderChildren) => <Box flexDirection="column">{mine}{await next(e)}</Box>

    const snap = await read($, readings)
    const base = await read($, turnBase)
    const cacheLeft = await read($, cacheLeftMin)
    const now = await $.clock.now()
    const gauge = gaugeFit(
      gaugeSegments({
        fiveHour: snap?.fiveHour ?? undefined,
        resetMs: snap?.fiveHourResetsAt == null ? undefined : Date.parse(snap.fiveHourResetsAt) - now,
        sevenDay: snap?.sevenDay ?? undefined,
        turnBurn: base === null || snap?.fiveHour == null ? null : turnDelta(base, snap.fiveHour),
        heavyTurnPct: config.heavy?.turnPct ?? 5,
        cacheLeft,
        contextTokens: snap?.contextTokens ?? undefined,
        spawns: await read($, spawns),
      }),
      e.props.bodyColumns,
    )

    const size = e.props.isWorking ? null : await read($, bandSize)
    if (gauge.length === 0 && size === null) return next(e)

    const gaugeRow =
      gauge.length === 0 ? null : (
        <Box>
          {gauge.flatMap((seg, i) => [
            i === 0 || seg.sep === '' ? null : (
              <Text key={`s${i}`} dimColor>
                {seg.sep}
              </Text>
            ),
            <Text key={`t${i}`} wrap="truncate" {...TONE[seg.tone]}>
              {seg.text}
            </Text>,
          ])}
        </Box>
      )
    if (size === null) return withBelow(gaugeRow)

    const layout = bandLayout({ columns: e.props.bodyColumns, note: bandCacheText(cacheLeft) })
    return withBelow(
      <Box flexDirection="column">
        {gaugeRow}
        <Box gap={3}>
          {layout.text === '' ? null : (
            <Text key="band-note" color="yellow" wrap="truncate">
              {layout.text}
            </Text>
          )}
          <Button plain key="handoff" hotkey="h" label={HANDOFF_LABEL} onPress={() => startHandoff($)} />
          {layout.hasIgnore ? <Button plain dimColor key="ignore" hotkey="i" label={IGNORE_LABEL} onPress={() => ignoreBand($)} /> : null}
        </Box>
      </Box>
    )
  })
}

