import type { BurnGuardTier } from '../types'

export const EXPENSIVE_PER_TURN = 2
export const CACHE_TTL_MS = 60 * 60 * 1000

/**
 * Tier of a model name, alias or full ID ("fable", "claude-opus-5-5", "Opus 5.5").
 * An unrecognised name counts as expensive: over-counting costs a confirm,
 * under-counting costs the 5h window.
 */
export function tierOf(model: string): BurnGuardTier {
  const m = model.toLowerCase()
  if (m.includes('fable')) return 'fable'
  if (m.includes('sonnet') || m.includes('haiku')) return 'cheap'
  return 'expensive'
}

/** The `model:` line of an agent file's frontmatter, or undefined. */
export function frontmatterModel(agentFile: string): string | undefined {
  const block = /^---\r?\n([\s\S]*?)\r?\n---/.exec(agentFile)?.[1]
  const model = block === undefined ? undefined : /^model:\s*['"]?([^'"\s]+)/m.exec(block)?.[1]
  return model === undefined || model === 'inherit' ? undefined : model
}

export type ModelSource = 'input' | 'frontmatter' | 'learned' | 'default-subagent' | 'session'

/**
 * The model an Agent call will run on, in the Agent tool's own precedence:
 * explicit `model` input, the definition's frontmatter (or, for a built-in with
 * no file, the model an earlier spawn of it resolved to), the configured
 * default subagent model, then the session's. A `fork` always inherits the session's.
 */
export function resolveModel(args: {
  subagentType: string | undefined
  inputModel: string | undefined
  frontmatter: string | undefined
  learned?: string
  defaultSubagent: string | undefined
  session: string
}): { model: string; source: ModelSource } {
  if (args.subagentType === 'fork') return { model: args.session, source: 'session' }
  if (args.inputModel) return { model: args.inputModel, source: 'input' }
  if (args.frontmatter) return { model: args.frontmatter, source: 'frontmatter' }
  if (args.learned) return { model: args.learned, source: 'learned' }
  if (args.defaultSubagent) return { model: args.defaultSubagent, source: 'default-subagent' }
  return { model: args.session, source: 'session' }
}

const FABLE_REQUEST =
  /\b(?:ask|use|have|get|let|run|spawn|call|consult|involve|send|by|via|loop\s+in|bring\s+in|check\s+with|escalate\s+to)\s+(?:the\s+|it\s+to\s+)?fable\b|\bfable[-\s]advisor\b|\bfable[,:]?\s+(?:to\s+|should\s+|can\s+|could\s+)?(?:look|review|check|audit|investigate|examine|weigh|analy[sz]e|go\s+over)\b/gi
const NEGATED = /\b(?:don'?t|do\s+not|never|not|no|without)\s+(?:\w+\s+){0,2}$/i

/**
 * Whether the user's prompt this turn actually asks for Fable (the manual-only
 * unlock): a verb aimed at Fable ("ask/use/have/get/let/run fable", "run it by fable"),
 * Fable as the one doing the work ("fable review this"), or "fable advisor".
 * A passing mention ("is fable cheaper?") doesn't count.
 * A request negated within two words before it ("don't use fable") doesn't count.
 */
export function requestsFable(prompt: string): boolean {
  for (const m of prompt.matchAll(FABLE_REQUEST)) {
    if (!NEGATED.test(prompt.slice(0, m.index))) return true
  }
  return false
}

/**
 * The model a spawn taught us its agent type runs on when the call names none:
 * the resolved model when it differs from the parent's (the definition pins
 * one), undefined when it simply inherited.
 */
export const learnedModel = (resolved: string, parent: string): string | undefined =>
  resolved === parent ? undefined : resolved

/** The 5h window's growth since the turn began; a reading below the base means it reset mid-turn. */
export const turnDelta = (base: number, current: number): number => (current >= base ? current - base : current)

// ── Gauge row ───────────────────────────────────────────────────────────────

export type Tone = 'plain' | 'dim' | 'info' | 'meta' | 'ok' | 'warn' | 'bad'
/** One piece of the gauge: `sep` is what joins it to the piece before; a higher `rank` is dropped first when narrow. */
export type GaugeSegment = { text: string; tone: Tone; rank: number; sep: string }

export const BAR_CELLS = 8
export const WARN_WINDOW_PCT = 60
export const BAD_WINDOW_PCT = 80

/** `▰▰▰▱▱▱▱▱`: a nonzero reading always fills at least one cell, a full-scale one fills all. */
export function windowBar(pct: number, cells = BAR_CELLS): string {
  const raw = Math.round((pct / 100) * cells)
  const filled = Math.min(cells, Math.max(pct > 0 ? 1 : 0, raw))
  return '▰'.repeat(filled) + '▱'.repeat(cells - filled)
}

export const windowTone = (pct: number): Tone => (pct >= BAD_WINDOW_PCT ? 'bad' : pct >= WARN_WINDOW_PCT ? 'warn' : 'ok')

/** `45m`, `2h10m`, `1d4h`; `now` once the reset is due. */
export function formatReset(ms: number): string {
  const minutes = Math.ceil(ms / 60_000)
  if (minutes <= 0) return 'now'
  if (minutes < 60) return `${minutes}m`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `${hours}h${String(minutes % 60).padStart(2, '0')}m`
  return `${Math.floor(hours / 24)}d${hours % 24}h`
}

const roundTenth = (n: number): number => Math.round(n * 10) / 10

/**
 * The gauge's pieces in display order: the 5h window (bar, %, time to reset),
 * the 7d window beside it, this turn's burn once it is visible, cache warmth,
 * context size, and the expensive-spawn count only once one is used.
 */
export function gaugeSegments(args: {
  fiveHour: number | undefined
  /** Milliseconds until the 5h window resets. */
  resetMs: number | undefined
  sevenDay: number | undefined
  /** Null when the turn's base reading is unknown. */
  turnBurn: number | null
  heavyTurnPct: number
  /** Whole minutes of cache left; null before the first response. */
  cacheLeft: number | null
  contextTokens: number | undefined
  spawns: number
}): GaugeSegment[] {
  const out: GaugeSegment[] = []
  if (args.fiveHour !== undefined) {
    out.push({ text: `5h ${windowBar(args.fiveHour)} ${Math.round(args.fiveHour)}%`, tone: windowTone(args.fiveHour), rank: 0, sep: '' })
    if (args.resetMs !== undefined) out.push({ text: `↻ ${formatReset(args.resetMs)}`, tone: 'info', rank: 4, sep: ' ' })
  }
  if (args.sevenDay !== undefined) {
    out.push({ text: `7d ${Math.round(args.sevenDay)}%`, tone: windowTone(args.sevenDay), rank: 5, sep: ' · ' })
  }
  if (args.turnBurn !== null && args.turnBurn >= 0.1) {
    out.push({ text: `+${roundTenth(args.turnBurn)}% turn`, tone: args.turnBurn > args.heavyTurnPct ? 'warn' : 'meta', rank: 2, sep: ' · ' })
  }
  if (args.cacheLeft !== null) {
    const cold = args.cacheLeft <= 0
    out.push({
      text: cold ? 'cache cold' : `cache ${args.cacheLeft}m`,
      tone: cold ? 'bad' : args.cacheLeft <= HANDOFF_NUDGE_MIN ? 'warn' : 'meta',
      rank: 3,
      sep: ' · ',
    })
  }
  if (args.contextTokens !== undefined) {
    out.push({ text: `ctx ${Math.round(args.contextTokens / 1000)}K`, tone: 'meta', rank: 6, sep: ' · ' })
  }
  if (args.spawns > 0) {
    out.push({ text: `exp ${args.spawns}/${EXPENSIVE_PER_TURN}`, tone: args.spawns >= EXPENSIVE_PER_TURN ? 'bad' : 'warn', rank: 1, sep: ' · ' })
  }
  return out
}

/** What fits in `columns`: the highest-rank piece goes first, repeatedly; the 5h bar is never dropped. */
export function gaugeFit(segments: GaugeSegment[], columns: number): GaugeSegment[] {
  const width = (segs: GaugeSegment[]) => segs.reduce((n, seg, i) => n + seg.text.length + (i === 0 ? 0 : seg.sep.length), 0)
  let kept = segments
  while (kept.length > 1 && width(kept) > columns) {
    const drop = kept.reduce((worst, seg) => (seg.rank > worst.rank ? seg : worst))
    kept = kept.filter(seg => seg !== drop)
  }
  return kept
}

/**
 * The once-per-countdown nudge: its text when the cache has at most `leadMs`
 * left and this countdown (keyed by `lastResponseAt`) hasn't been nudged yet.
 */
export function cacheNudge(args: {
  now: number
  lastResponseAt: number | null
  nudgedFor: number | null
  leadMs: number
}): string | undefined {
  if (args.lastResponseAt === null || args.nudgedFor === args.lastResponseAt) return undefined
  const left = CACHE_TTL_MS - (args.now - args.lastResponseAt)
  if (left <= 0 || left > args.leadMs) return undefined
  return `cache expires in ${Math.ceil(left / 60_000)}m — send now or let it go`
}

/**
 * Heavy-turn alerts for one 5h reading: the turn's burn passing `turnPct`
 * (once per turn) and the window crossing `windowPct` upward.
 */
export function heavyAlerts(args: {
  base: number | null
  previous: number | null
  current: number
  turnAlerted: boolean
  turnPct: number
  windowPct: number
}): { toasts: string[]; turnAlerted: boolean } {
  const toasts: string[] = []
  let turnAlerted = args.turnAlerted
  if (!turnAlerted && args.base !== null) {
    const delta = turnDelta(args.base, args.current)
    if (delta > args.turnPct) {
      toasts.push(`heavy turn: +${Math.round(delta * 10) / 10}% of the 5h window so far`)
      turnAlerted = true
    }
  }
  if (args.previous !== null && args.previous < args.windowPct && args.current >= args.windowPct) {
    toasts.push(`5h window at ${args.current}% (crossed ${args.windowPct}%)`)
  }
  return { toasts, turnAlerted }
}

// ── Handoff band ────────────────────────────────────────────────────────────

/** At or under this many minutes of cache left, the band urges a handoff while the re-read is cheap. */
export const HANDOFF_NUDGE_MIN = 10

/** Whole minutes of prompt cache left (0 once cold); null before the first response. */
export function cacheMinutesLeft(now: number, lastResponseAt: number | null): number | null {
  if (lastResponseAt === null) return null
  return Math.max(0, Math.ceil((CACHE_TTL_MS - (now - lastResponseAt)) / 60_000))
}

/**
 * Whether the band shows for a context of `size` tokens at turn end: past the
 * threshold, not quieted, and — after one [i] — grown `step` past the ignored size.
 */
export function bandVisible(args: {
  size: number | undefined
  threshold: number
  step: number
  ignoredAt: number | null
  quiet: boolean
}): boolean {
  if (args.quiet || args.size === undefined || args.size < args.threshold) return false
  return args.ignoredAt === null || args.size >= args.ignoredAt + args.step
}

/**
 * The band's one note, only when the cache argues for acting now: the hand-off-now
 * nudge or the cold warning. A healthy countdown has none: the gauge row shows it.
 */
export function bandCacheText(minutesLeft: number | null): string | undefined {
  if (minutesLeft === null) return undefined
  if (minutesLeft <= 0) return 'cache cold — handoff will cost full price'
  if (minutesLeft <= HANDOFF_NUDGE_MIN) return `cache cold in ${minutesLeft}m — hand off now while it's cheap`
  return undefined
}

export const HANDOFF_LABEL = 'handoff + clear'
export const IGNORE_LABEL = 'ignore'
// A plain terminal Button with a hotkey draws `h: label`; the band's Box puts BAND_GAP cells between its pieces.
const BAND_GAP = 3
const buttonCells = (label: string) => label.length + 3 + BAND_GAP

/**
 * What fits in `columns` beside the buttons: the note and both buttons, then
 * without the note, then without [i]. [h] is never dropped.
 */
export function bandLayout(args: { columns: number; note: string | undefined }): {
  text: string
  hasIgnore: boolean
} {
  const candidates = [
    { text: args.note ?? '', hasIgnore: true },
    { text: '', hasIgnore: true },
    { text: '', hasIgnore: false },
  ]
  const fits = (c: { text: string; hasIgnore: boolean }) =>
    (c.text === '' ? 0 : c.text.length + BAND_GAP) + buttonCells(HANDOFF_LABEL) - BAND_GAP + (c.hasIgnore ? buttonCells(IGNORE_LABEL) : 0) <= args.columns
  return candidates.find(fits) ?? { text: '', hasIgnore: false }
}

/**
 * Whether a Write is /session-handoff saving its dated file
 * (`~/.claude/handoffs/<date>-<HHMM>[-min].md`), not the `latest.md` pin.
 */
export const isHandoffDraft = (path: string): boolean =>
  /\/\.claude\/handoffs\/[^/]+\.md$/.test(path) && !path.endsWith('/latest.md')

