// Tiers: expensive = aliases `fable` + `opus`; `fable` alone is manual-only (fableManualOnly).
export type BurnGuardTier = 'fable' | 'expensive' | 'cheap'

declare module 'claude-code' {
  interface PluginState {
    'burn-guard': {
      /** The user's own prompt text for the current turn ('' when the turn wasn't theirs). */
      prompt: string
      /** Expensive-tier spawns allowed so far this turn. */
      spawns: number
      /** 5h rate-limit % at turn start; null until a reading exists. */
      turnBase: number | null
      /** Epoch ms of the last main-thread model response; null before the first. */
      lastResponseAt: number | null
      /** The `lastResponseAt` whose countdown was already nudged; null when none. */
      nudgedFor: number | null
      /** The last 5h % a measurement reported; null until one did. */
      lastFiveHour: number | null
      /** Whether this turn already raised the heavy-turn toast. */
      heavyAlerted: boolean
      /** Usage the gauge row draws, refreshed ~once a minute and on turn events; null before the first read. */
      readings: {
        /** 5h window % used; null off a subscription. */
        fiveHour: number | null
        /** ISO time the 5h window resets. */
        fiveHourResetsAt: string | null
        sevenDay: number | null
        /** Input tokens the last response was answered over. */
        contextTokens: number | null
      } | null
      /** Whole minutes of prompt cache left (0 = cold), ticked ~once a minute; null before the first response. */
      cacheLeftMin: number | null
      /** Context size the handoff band shows, set at turn end; null while the band is hidden. */
      bandSize: number | null
      /** Context size at the first [i] press this session; null while not ignored. */
      bandIgnoredAt: number | null
      /** Set by a second [i]: the band stays hidden for the rest of the session. */
      bandQuiet: boolean
      /** Epoch ms of the [h] press whose handoff turn hasn't completed yet; null otherwise. */
      handoffPressedAt: number | null
      /** The dated handoff file this session's own Write created after the [h] press; null until then. */
      handoffDraft: string | null
    }
  }
}
